const app=document.querySelector('#app');
const labels={customer_acquisition:'Customer acquisition',sales_conversion:'Sales conversion',delivery_capacity:'Delivery capacity',retention:'Retention',unit_economics:'Unit economics',strategic_focus:'Strategic focus',insufficient_information:'Insufficient information'};
const metricLabels={diagnosis_agreement:'Diagnosis agreement',grounded_advice:'Grounded advice',missing_information:'Missing information',label_match:'Exact label match'};
const state={page:'advisor',caseId:'agency',variant:'grounded',filter:'all',inspectId:'agency',inspectVariant:'grounded',busy:false};
let bundle,prompts,report=null,localServer=false,storageAvailable=true;
const referenceQuestions={agency:'What customer acquisition cost would still leave attractive profit per engagement, and how many new clients can you serve?',golf:'How do contribution profit, retention and founder dependence compare between sponsorships and the subscription?',cloud:'Which parts of the initial implementation can be reduced or standardized without compromising ongoing service quality?'};
function visibleBrief(c){const output=result(c.id,state.variant);if(output)return output;if(state.variant!=='reference')return null;return {origin:'consultation_reference',brief:{constraint:c.reference.constraint,diagnosis:c.reference.diagnosis,evidence:c.inputs.facts,next_action:c.reference.action,follow_up_question:referenceQuestions[c.id],missing_information:c.inputs.unknowns,source_ids:[]}};}
let reportPoll=null;
let reviews={};try{reviews=JSON.parse(localStorage.getItem('constraint-reviews-v1')||'{}');if(!reviews||Array.isArray(reviews)||typeof reviews!=='object')reviews={};}catch{storageAvailable=false;}
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name)=>{const paths={brief:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6M9 12h6M9 16h4"/>',eval:'<path d="M4 20h16M7 16V9M12 16V4M17 16v-5"/>',method:'<path d="M12 4v16M4 5h5a3 3 0 0 1 3 3 3 3 0 0 1 3-3h5v14h-5a3 3 0 0 0-3 1 3 3 0 0 0-3-1H4z"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true">${paths[name]||paths.brief}</svg>`;};
const currentCase=()=>bundle.cases.find(c=>c.id===state.caseId);
const result=(id,variant)=>report?.results.find(r=>r.case_id===id&&r.variant===variant);
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),3500);}
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function shell(content,title,subtitle,actions=''){
return `<div class="shell"><aside class="sidebar"><div><div class="brand"><span class="mark" aria-hidden="true"><i></i><i></i><i></i><i></i></span>constraint</div><div class="sidebar-sub">Advisor workspace</div></div><div class="nav-label">Workspace</div><nav class="nav" aria-label="Main navigation"><button data-page="advisor" class="${state.page==='advisor'?'active':''}" ${state.page==='advisor'?'aria-current="page"':''}>${icon('brief')}Consultations<span class="count">03</span></button><button data-page="eval" class="${state.page==='eval'?'active':''}" ${state.page==='eval'?'aria-current="page"':''}>${icon('eval')}Evaluations</button><button data-page="method" class="${state.page==='method'?'active':''}" ${state.page==='method'?'aria-current="page"':''}>${icon('method')}Methodology</button></nav><div class="sidebar-bottom"><b>Built by Devin Padron</b>Independent interview prototype<br>Inspired by the Scaling Roadmap</div></aside><main class="main"><div class="topbar"><div class="breadcrumb">Workspace<span>/</span><b>${state.page==='advisor'?'Consultations':state.page==='eval'?'Evaluations':'Methodology'}</b></div><span class="status">${report?'Real model outputs':'Reference preview · Model run pending'}</span></div><header class="pagehead"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></header>${state.busy?'<div class="liveprogress" aria-label="Evaluation running"><i></i></div>':''}${content}<footer class="footer"><span>3 public consultations · Provisional references · Advisor judgment required</span><span>${report?`${escape(report.model)} · Saved run ${escape(report.run_id)}`:'OpenAI outputs pending · Source-derived reference preview'}</span></footer></main></div><input class="inputfile" id="import-run" type="file" accept=".json,application/json"><dialog class="dialog" id="dialog"></dialog>`;
}
function advisor(){
 const c=currentCase(),r=visibleBrief(c),saved=reviews[c.id];
 const queue=bundle.cases.map((x,i)=>`<button data-case="${x.id}" class="casebtn ${x.id===c.id?'active':''}" ${x.id===c.id?'aria-pressed="true"':'aria-pressed="false"'}><span class="case-index">CASE 0${i+1}${reviews[x.id]?'<span class="reviewdot">✓</span>':''}</span><strong>${escape(x.name)}</strong><small>${escape(x.revenue)} · ${escape(x.sector.split(' / ')[0])}</small></button>`).join('');
 const source=`<details class="details"><summary>Business intake & consultation source</summary><div class="detailbody"><p>${escape(c.inputs.business)}</p><ul>${c.inputs.facts.map(f=>`<li>${escape(f)}</li>`).join('')}</ul><a href="${escape(c.source.url)}" target="_blank" rel="noopener">${escape(c.source.title)} ↗</a><p class="ref-label">Input: ${escape(c.source.input_window)} · Captions may contain errors.</p><p>Owner facts were paraphrased into the intake. Consultation advice is withheld from the model and used only for scoring.</p></div></details><details class="details"><summary>Consultation-derived reference</summary><div class="detailbody"><h4>${labels[c.reference.constraint]}</h4><p>${escape(c.reference.diagnosis)}</p><p>${escape(c.reference.action)}</p><a href="${escape(c.source.url)}&t=${c.source.reference_seconds}s" target="_blank" rel="noopener">Watch the consultation advice ↗</a><p class="ref-label">${escape(c.reference.caution)}</p></div></details>`;
 const body=r?`<section class="diagnosis"><div class="eyebrow">${r.origin==='consultation_reference'?'Consultation reference':'Proposed primary constraint'}<span class="tag">${r.origin==='consultation_reference'?'Caption-derived':'Needs advisor review'}</span></div><h3>${labels[r.brief.constraint]}</h3><p>${escape(r.brief.diagnosis)}</p></section><div class="sectionlabel">Evidence from the intake</div><ul class="evidence-list">${r.brief.evidence.map(e=>`<li>${escape(e)}</li>`).join('')}</ul><section class="next-action"><span class="step-num">01</span><div><h4>${r.origin==='consultation_reference'?'Consultation recommendation':'Next action to test'}</h4><p>${escape(r.brief.next_action)}</p></div></section><section class="question"><div class="sectionlabel">${r.origin==='consultation_reference'?'Suggested validation question':'Ask before committing'}</div><p>${escape(r.brief.follow_up_question)}</p><small>Missing: ${r.brief.missing_information.map(escape).join(' · ')}</small></section>${r.origin==='consultation_reference'?'<p class="review-caption">This is a paraphrase of the consultation advice, not an AI output. The validation question is an analyst-written suggestion.</p>':`<details class="details"><summary>Framework context & model output</summary><div class="detailbody"><p>${state.variant==='grounded'?'The model received three fixed roadmap summaries. This prototype does not perform automated retrieval.':'The baseline received only the business intake, with no roadmap context.'}</p>${r.brief.source_ids.map(id=>{const s=prompts.framework.find(x=>x.id===id);return s?`<p><a href="${escape(s.url)}" target="_blank" rel="noopener">${escape(s.title)} ↗</a><br>${escape(s.text)}</p>`:'';}).join('')}<p class="ref-label">${r.latency_seconds.toFixed(2)}s inference · ${r.usage.input_tokens??'—'} input tokens · ${r.usage.output_tokens??'—'} output tokens · Prompt ${escape(report.prompt_version)}</p></div></details>`}`:'<div class="pending">The business intake is ready. Model output will appear when the evaluation finishes.</div>';
 return shell(`<div class="workspace"><aside class="queue"><div class="queue-head"><span class="sectionlabel">Consultation queue</span><span>3 cases</span></div>${queue}<p class="queue-note">From real MoreMozi consultations.<br>Advice becomes a reference.<br>Reviews become the next dataset.</p></aside><article class="brief"><div class="brief-heading"><div><div class="sectionlabel">Consultation brief / 0${bundle.cases.indexOf(c)+1}</div><h2>${escape(c.name)}</h2><p>${escape(c.sector)}</p></div><div class="toggle" aria-label="Prompt configuration">${!report?`<button data-variant="reference" class="${state.variant==='reference'?'active':''}" aria-pressed="${state.variant==='reference'}">Reference</button>`:''}<button data-variant="baseline" class="${state.variant==='baseline'?'active':''}" aria-pressed="${state.variant==='baseline'}">Baseline</button><button data-variant="grounded" class="${state.variant==='grounded'?'active':''}" aria-pressed="${state.variant==='grounded'}">Grounded</button></div></div><div class="facts"><div><small>ANNUAL REVENUE</small><b>${escape(c.revenue)}</b></div><div><small>GROWTH GOAL</small><b>${escape(c.goal)}</b></div><div><small>TEAM SIZE</small><b>${c.inputs.headcount?`${c.inputs.headcount} people`:'Not provided'}</b></div></div>${body}${source}<section class="review"><div class="review-head"><h4>Advisor decision</h4><span>${saved?'Review saved':'Draft until reviewed'}</span></div><div class="review-controls"><button data-review="accept" class="${saved?.decision==='accept'?'selected':''}" ${r?'':'disabled'}>✓ Accept brief</button><button data-review="correct" class="${saved?.decision==='correct'?'selected-correct':''}" ${r?'':'disabled'}>Correct diagnosis</button><button data-review="follow_up" class="${saved?.decision==='follow_up'?'selected':''}" ${r?'':'disabled'}>Needs follow-up</button></div><div id="review-editor"></div>${saved?'<button id="remove-review" class="quiet">Remove this review</button>':''}${saved?`<p class="review-caption">${escape(saved.decision==='correct'?labels[saved.constraint]:saved.decision==='follow_up'?'More information requested':'Accepted '+labels[saved.constraint])}${saved.note?' · '+escape(saved.note):''}</p>`:''}<p class="review-caption">Reviews are saved in this browser${storageAvailable?'': ' session (storage unavailable)'}. Export them to retain or add to a reviewed dataset.</p></section></article></div>`,'Consultation workspace','A focused brief. A testable next move. A human decision.',`<button id="export-review">Export reviews ↗</button><button data-page="eval" class="primary">Compare evaluations →</button>`);
}
function scoreCell(v){return `<span class="score ${v<.8?'low':''}">${Math.round(v*100)}%</span>`;}
function evaluation(){
 if(!report)return shell(`<div class="eval-note">No model run has completed. The configured OpenAI account reported exhausted credits. Reference labels below come from the consultations; predictions, scores and latency will appear only after real API calls succeed.</div><div class="eval-table-wrap"><table><thead><tr><th>Business case</th><th>Prompt</th><th>Reference constraint</th><th>Prediction</th><th>Scores</th><th>Latency</th></tr></thead><tbody>${bundle.cases.flatMap(c=>['baseline','grounded'].map(v=>`<tr><td>${escape(c.name)}</td><td>${v==='baseline'?'Baseline':'Grounded'}</td><td>${labels[c.reference.constraint]}</td><td>Awaiting run</td><td>—</td><td>—</td></tr>`)).join('')}</tbody></table></div>`,'Evaluation comparison','Same cases. Same model. Two prompt configurations.',`<button id="import-results">Import run</button><button id="run-eval" class="primary" ${state.busy?'disabled':''}>${state.busy?'Running…':localServer?'Run evaluation ↻':'Rerun setup ↗'}</button>`);
 const keys=['diagnosis_agreement','grounded_advice','missing_information'];
 const summaries=keys.map(k=>`<section class="metric-summary"><h3>${metricLabels[k]}</h3>${['baseline','grounded'].map(v=>{const rows=report.results.filter(r=>r.variant===v),mean=rows.reduce((n,r)=>n+r.scores[k].score,0)/rows.length;return `<div class="metric-line ${v}"><span>${v==='baseline'?'Baseline':'Grounded'}</span><div class="bar"><i style="width:${Math.round(mean*100)}%"></i></div><b>${Math.round(mean*100)}%</b></div>`;}).join('')}</section>`).join('');
 const filtered=report.results.filter(r=>state.filter!=='review'||keys.some(k=>r.scores[k].score<.8));
 const table=filtered.map(r=>{const c=bundle.cases.find(x=>x.id===r.case_id);return `<tr data-eval-case="${c.id}" data-eval-variant="${r.variant}"><td><button class="linkbutton" data-inspect="${c.id}" data-inspect-variant="${r.variant}">${escape(c.name)}</button><small>Reference: ${labels[c.reference.constraint]}</small></td><td><span class="variant-dot ${r.variant}"></span>${r.variant==='baseline'?'Baseline':'Grounded'}</td><td>${labels[r.brief.constraint]}<small>${r.scores.label_match.score===1?'Label matches reference':'Different reference label'}</small></td>${keys.map(k=>`<td>${scoreCell(r.scores[k].score)}</td>`).join('')}<td>${r.latency_seconds.toFixed(2)}s</td></tr>`;}).join('');
 const active=result(state.inspectId,state.inspectVariant),selected=bundle.cases.find(x=>x.id===state.inspectId);
 const inspector=active?`<section class="eval-inspect"><div class="review-head"><h3>${escape(selected.name)} · ${state.inspectVariant==='baseline'?'Baseline':'Grounded'}</h3><button data-open-brief="${selected.id}" data-open-variant="${state.inspectVariant}">Open brief →</button></div><div class="compare-predictions"><div><div class="sectionlabel">Model output</div><strong>${labels[active.brief.constraint]}</strong><p>${escape(active.brief.next_action)}</p></div><div><div class="sectionlabel">Consultation reference</div><strong>${labels[selected.reference.constraint]}</strong><p>${escape(selected.reference.action)}</p><a href="${escape(selected.source.url)}&t=${selected.source.reference_seconds}s" target="_blank" rel="noopener">Source consultation ↗</a></div></div>${keys.map(k=>`<div class="grade-row"><div class="gradehead"><span>${metricLabels[k]}</span>${scoreCell(active.scores[k].score)}</div><p>${escape(active.scores[k].reason)}</p></div>`).join('')}</section>`:'';
 return shell(`<div class="runline"><span>RUN <code>${escape(report.run_id)}</code></span><span>${escape(report.model)}</span><span>Temperature 0 · 1 sample per case · 6 outputs</span></div><div class="eval-overview">${summaries}</div><div class="eval-toolbar"><div class="toggle"><button data-filter="all" class="${state.filter==='all'?'active':''}">All outputs</button><button data-filter="review" class="${state.filter==='review'?'active':''}">Below 80%</button></div><p>Scores are LLM judgments; exact label match is checked in code.</p></div><div class="eval-table-wrap"><table><thead><tr><th>Business case</th><th>Prompt</th><th>Predicted constraint</th><th>Diagnosis</th><th>Grounding</th><th>Missing info</th><th>Latency</th></tr></thead><tbody>${table||'<tr><td colspan="7" class="empty">No scores below 80% in this run.</td></tr>'}</tbody></table></div><p class="eval-note">Three selected cases demonstrate the evaluation workflow. They do not establish general accuracy or prove that one prompt is better. References are provisional, and the judge uses the same model family as the advisor. Select an output to inspect its grading explanation.</p>${inspector}`,'Evaluation comparison','Same cases. Same model. Two prompt configurations.',`<button id="import-results">Import run</button><button id="export-run">Export run</button><button id="run-eval" class="primary" ${state.busy?'disabled':''}>${state.busy?'Running…':localServer?'Run evaluation ↻':'Rerun setup ↗'}</button>`);
}
function methodology(){return shell(`<div class="methodology"><section class="method-section"><h3>01 / A small, traceable evaluation set</h3><p>Three real business consultations from MoreMozi. The owner’s statements are paraphrased into an intake. The consultation advice is separately summarized as a provisional reference. Automatic captions and analyst interpretation can introduce errors; expert review is the next step.</p><p>Inputs include owner statements made after the advisor started speaking. This is a consultation-informed snapshot, not a prospective test of diagnosis from the opening question alone. Reference answers are withheld from both prompts and framework context; model pretraining exposure is unknown.</p></section><section class="method-section"><h3>02 / One controlled prompt comparison</h3><p>Both configurations use the same model, schema and cases at temperature 0. The grounded variant adds decision rules and three fixed roadmap summaries. This is prompt-and-context engineering. No model training or automated retrieval is used.</p><details class="details"><summary>Baseline system prompt</summary><pre>${escape(prompts.baseline)}</pre></details><details class="details"><summary>Grounded system prompt</summary><pre>${escape(prompts.grounded)}</pre></details>${prompts.framework.map(s=>`<div class="source-note"><h4><a href="${escape(s.url)}" target="_blank" rel="noopener">${escape(s.title)} ↗</a></h4><p>${escape(s.text)}</p><span class="ref-label">${escape(s.locator)} · ${escape(s.id)}</span></div>`).join('')}</section><section class="method-section"><h3>03 / Separate validity from judgment</h3><p>Code validates the response schema, source IDs and exact reference-label agreement. An OpenAI model judges substantive diagnosis and action agreement, factual grounding, and handling of missing information on a 0–1 scale. The 80% filter is an exploratory review aid, not a release gate.</p><details class="details"><summary>Read the complete grading rubric</summary><pre>${escape(report?.judge_rubric||'The rubric appears with the first completed run.')}</pre></details><p>Inference latency is measured around each API call, including retries and schema parsing. Judge time is excluded. Token usage is reported from the API. One sample per case is insufficient to quantify variance.</p></section><section class="method-section"><h3>04 / Close the human review loop</h3><p>An advisor can accept a brief, correct the constraint and next action, or request more information. Reviews stay in the browser until exported. Exported reviews need independent quality checks before becoming reference labels. The model’s own outputs are never automatically promoted to ground truth.</p></section><section class="method-section"><h3>05 / What to test next</h3><ol><li>Independently review labels and add ambiguous or incomplete intakes.</li><li>Split development and evaluation cases by business and source video.</li><li>Repeat runs and calibrate the judge against human decisions.</li><li>Measure advisor agreement, useful follow-up questions, and eventually business outcomes.</li></ol></section></div>`,'How the prototype works','Sources, prompts and evaluation assumptions you can inspect.',`<button data-page="advisor" class="primary">Back to consultations →</button>`);}
function render(){app.innerHTML=state.page==='advisor'?advisor():state.page==='eval'?evaluation():methodology();bind();}
function navigate(page){if(!['advisor','eval','method'].includes(page))throw new Error('Unknown page');state.page=page;render();window.scrollTo({top:0,behavior:'instant'});}
function saveReview(decision,fields={}){const c=currentCase(),r=visibleBrief(c);if(!r)throw new Error('No brief to review');const record={case_id:c.id,decision,constraint:fields.constraint||r.brief.constraint,next_action:fields.next_action||r.brief.next_action,note:fields.note||'',variant:state.variant,run_id:report?.run_id||null,origin:r.origin||'openai_model',reviewed_at:new Date().toISOString(),inputs:c.inputs,model_output:r.origin?null:r.brief,reference_brief:r.origin?r.brief:null,source_url:c.source.url,reference_status:'Advisor review; independent verification pending'};reviews[c.id]=record;try{localStorage.setItem('constraint-reviews-v1',JSON.stringify(reviews));}catch{storageAvailable=false;}render();toast(storageAvailable?'Review saved in this browser.':'Review retained for this session. Export to save it.');return record;}
function reviewEditor(decision){const c=currentCase(),r=visibleBrief(c),saved=reviews[c.id];if(decision==='accept'){saveReview('accept');return;}
 const host=document.querySelector('#review-editor');host.innerHTML=`<form class="review-editor" id="review-form">${decision==='correct'?`<div class="field"><label for="correct-constraint">Corrected primary constraint</label><select id="correct-constraint" name="constraint">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${k===(saved?.constraint||r.brief.constraint)?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="correct-action">Revised next action</label><textarea id="correct-action" name="next_action" required maxlength="4000">${escape(saved?.next_action||r.brief.next_action)}</textarea></div>`:''}<div class="field"><label for="review-note">${decision==='correct'?'Why does the recommendation change?':'What information should we ask for?'}</label><textarea id="review-note" name="note" required maxlength="4000" placeholder="Add the evidence or question that changes the decision.">${escape(saved?.note||'')}</textarea></div><button class="primary" type="submit">Save ${decision==='correct'?'correction':'follow-up'}</button><button type="button" id="cancel-review" class="quiet">Cancel</button></form>`;document.querySelector('#review-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(!data.note.trim()){toast('Add a review note.');return;}saveReview(decision,data);};document.querySelector('#cancel-review').onclick=()=>host.innerHTML='';host.querySelector('select,textarea').focus();}
function rerunDialog(){const d=document.querySelector('#dialog');d.innerHTML=`<div class="dialog-head"><h2>Run a fresh evaluation</h2><button id="close-dialog" aria-label="Close dialog">×</button></div><p>This hosted demo displays saved outputs from real OpenAI calls. Run the included Python project locally to generate six new outputs and their grades, then import the resulting report here.</p><pre>uv venv --python 3.12 .venv\nuv pip install --python .venv/bin/python -r requirements.txt\n# Configure OPENAI_API_KEY in your environment.\n.venv/bin/python eval/runner.py --run</pre><p>Output: <code>dist/report.json</code>. To rerun directly from the website, start <code>.venv/bin/python eval/server.py</code> and open its localhost address.</p><small>Your API key stays on the local server.</small>`;d.querySelector('#close-dialog').onclick=()=>d.close();d.showModal();}
async function runEval(){if(!localServer){rerunDialog();return;}if(state.busy)return;state.busy=true;render();try{const start=await fetch('/api/evaluate',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!start.ok)throw new Error((await start.json()).error||'Could not start evaluation');toast('Running six new outputs and grades…');let pending=true;while(pending){await new Promise(resolve=>setTimeout(resolve,1800));const response=await fetch('/api/status');if(!response.ok)throw new Error('Lost connection to the local runner');const job=await response.json();pending=job.status==='running';if(job.status==='failed')throw new Error(job.error||'Evaluation failed');}const next=await fetch('report.json?v='+Date.now()).then(r=>r.json());validateReport(next);report=next;toast('New evaluation loaded.');}catch(e){toast(e.message);}finally{state.busy=false;if(report&&state.variant==='reference')state.variant='grounded';render();}}
function validateReport(value){if(value?.schema_version!==1||!Array.isArray(value.results)||value.results.length!==6)throw new Error('Expected a complete report with 3 cases × 2 prompts.');if(value.dataset_version!==bundle.version||value.prompt_version!==prompts.version)throw new Error('Dataset or prompt version does not match this website.');if(report&&(value.dataset_hash!==report.dataset_hash||value.prompt_hash!==report.prompt_hash))throw new Error('Dataset or prompt content has changed. Update the site with the matching source files.');if(typeof value.model!=='string'||typeof value.run_id!=='string'||typeof value.judge_rubric!=='string')throw new Error('Report metadata is incomplete.');const seen=new Set();for(const r of value.results){const key=r.case_id+':'+r.variant;if(seen.has(key)||!bundle.cases.some(c=>c.id===r.case_id)||!['baseline','grounded'].includes(r.variant))throw new Error('Report contains unknown or duplicate outputs.');seen.add(key);const b=r.brief;if(!b||!labels[b.constraint]||['diagnosis','next_action','follow_up_question'].some(k=>typeof b[k]!=='string')||['evidence','missing_information','source_ids'].some(k=>!Array.isArray(b[k])||b[k].some(x=>typeof x!=='string')))throw new Error('Invalid model brief.');if(b.source_ids.some(id=>r.variant==='baseline'||!prompts.framework.some(s=>s.id===id)))throw new Error('Invalid source citation.');if(typeof r.latency_seconds!=='number'||!Number.isFinite(r.latency_seconds)||r.latency_seconds<0||!r.usage)throw new Error('Invalid latency or usage.');for(const k of Object.keys(metricLabels)){const m=r.scores?.[k];if(!m||typeof m.score!=='number'||!Number.isFinite(m.score)||m.score<0||m.score>1||typeof m.reason!=='string')throw new Error('Invalid score for '+k);}}return value;}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{state.caseId=b.dataset.case;render();});document.querySelectorAll('[data-variant]').forEach(b=>b.onclick=()=>{state.variant=b.dataset.variant;render();});document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>reviewEditor(b.dataset.review));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;render();});document.querySelectorAll('[data-eval-case]').forEach(row=>row.onclick=()=>{state.inspectId=row.dataset.evalCase;state.inspectVariant=row.dataset.evalVariant;render();});document.querySelectorAll('[data-open-brief]').forEach(b=>b.onclick=()=>{state.caseId=b.dataset.openBrief;state.variant=b.dataset.openVariant;navigate('advisor');});const actions={'remove-review':()=>{delete reviews[state.caseId];try{localStorage.setItem('constraint-reviews-v1',JSON.stringify(reviews));}catch{}render();toast('Review removed.');},'export-review':()=>{const entries=Object.values(reviews);if(!entries.length){toast('Review a consultation first, then export it.');return;}download('constraint-advisor-reviews.json',{schema_version:1,exported_at:new Date().toISOString(),dataset_version:bundle.version,reviews:entries});toast('Reviews exported.');},'export-run':()=>download('constraint-evaluation-'+report.run_id+'.json',report),'import-results':()=>document.querySelector('#import-run').click(),'run-eval':runEval};for(const [id,fn]of Object.entries(actions)){const b=document.getElementById(id);if(b)b.onclick=fn;}document.querySelector('#import-run').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>2000000){toast('Report is too large (maximum 2MB).');return;}try{const next=JSON.parse(await f.text());validateReport(next);report=next;if(state.variant==='reference')state.variant='grounded';clearInterval(reportPoll);render();toast('Imported evaluation run.');}catch(error){toast('Import failed: '+error.message);}};const dialog=document.querySelector('#dialog');dialog.onclick=e=>{if(e.target===dialog)dialog.close();};}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const controller=new AbortController();const tools=[{name:'read_constraint_workspace',description:'Read the current case, visible prompt variant, saved model brief and local advisor decisions.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).length)throw new Error('Expected an empty object');return {page:state.page,case_id:state.caseId,variant:state.variant,brief:visibleBrief(currentCase())?.brief||null,origin:visibleBrief(currentCase())?(visibleBrief(currentCase()).origin||'openai_model'):null,review:reviews[state.caseId]||null};}},{name:'navigate_constraint_case',description:'Select a consultation case and show its saved model brief. Does not run a model or save a review.',inputSchema:{type:'object',properties:{case_id:{type:'string',enum:bundle.cases.map(c=>c.id)},variant:{type:'string',enum:['baseline','grounded','reference']}},required:['case_id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).some(k=>!['case_id','variant'].includes(k))||!bundle.cases.some(c=>c.id===input.case_id)||(input.variant&&!['baseline','grounded','reference'].includes(input.variant)))throw new Error('Unknown case or variant');state.caseId=input.case_id;state.variant=input.variant||state.variant;navigate('advisor');return {case_id:state.caseId,variant:state.variant};}}];for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>controller.abort(),{once:true});}
try{[bundle,prompts]=await Promise.all(['cases.json','prompts.json'].map(u=>fetch(u).then(r=>{if(!r.ok)throw new Error('Could not load '+u);return r.json();})));try{const r=await fetch('report.json');if(r.ok){const data=await r.json();validateReport(data);report=data;}}catch{}try{if(['localhost','127.0.0.1'].includes(location.hostname)){const health=await fetch('/api/health');if(health.ok)localServer=(await health.json()).runner===true;}}catch{}if(!report)state.variant='reference';render();registerTools();if(!report&&localServer){reportPoll=setInterval(async()=>{try{const r=await fetch('report.json?v='+Date.now());if(r.ok){const next=await r.json();validateReport(next);report=next;if(state.variant==='reference')state.variant='grounded';clearInterval(reportPoll);render();toast('Real model outputs are ready.');}}catch{}},4000);}}catch(e){app.innerHTML=`<p class="error">${escape(e.message)}. Refresh to try again.</p>`;}
